/**
 * Cross-language model-pack conformance test (TS side / ORACLE).
 *
 * Loads every shared fixture under fixtures/modelpack/cases/* and runs the TS
 * verifier against it, asserting each matches its expected.json. The Rust crate
 * (modelpack/tests/conformance.rs) runs the SAME fixtures through the Rust
 * verifier — agreement across the two suites proves the implementations make
 * byte-for-byte-identical trust decisions (canonicalization + ed25519 parity).
 *
 * Fixtures are generated by scripts/gen-modelpack-fixtures.ts (signed with the
 * committed TEST-ONLY key). This is a NEW PERMANENT test: it intentionally
 * raises the committed core test count above 69.
 */
import { describe, it, expect } from "vitest";
import { createPublicKey } from "node:crypto";
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, resolve } from "node:path";

import { verifyModelPack, validateManifest } from "../src/index.js";

const here = dirname(fileURLToPath(import.meta.url));
const repoRoot = resolve(here, "../..");
const fixturesDir = resolve(repoRoot, "fixtures/modelpack");
const casesDir = resolve(fixturesDir, "cases");

interface Context {
  pubkeySpkiPem: string;
  pubkeyRawHex: string;
  engineVersions: Record<string, string>;
}

interface Expected {
  outcome: "ok" | "reject";
  reasonContains?: string;
}

const context: Context = JSON.parse(readFileSync(resolve(fixturesDir, "context.json"), "utf8"));
const publicKey = createPublicKey(context.pubkeySpkiPem);

const caseNames = readdirSync(casesDir, { withFileTypes: true })
  .filter((e) => e.isDirectory())
  .map((e) => e.name)
  .sort();

describe("model-pack cross-language conformance (TS oracle)", () => {
  it("has fixtures to run", () => {
    expect(caseNames.length).toBeGreaterThan(0);
  });

  for (const name of caseNames) {
    it(`case "${name}"`, () => {
      const dir = resolve(casesDir, name);
      const manifest: unknown = JSON.parse(readFileSync(resolve(dir, "manifest.json"), "utf8"));
      const expected: Expected = JSON.parse(readFileSync(resolve(dir, "expected.json"), "utf8"));

      const weightsPath = resolve(dir, "weights.bin");
      // Malformed-only cases have no weights: structural validation rejects
      // them before the hash step is ever reached, so validateManifest alone is
      // the right oracle (and mirrors what the Rust conformance test does).
      if (!existsSync(weightsPath)) {
        const v = validateManifest(manifest);
        expect(v.ok).toBe(false);
        expect(expected.outcome).toBe("reject");
        if (!v.ok && expected.reasonContains) {
          expect(v.reason).toContain(expected.reasonContains);
        }
        return;
      }

      const weights = new Uint8Array(readFileSync(weightsPath));
      const result = verifyModelPack(
        { manifest, weights },
        { publicKey, engineVersions: context.engineVersions },
      );

      if (expected.outcome === "ok") {
        expect(result.ok, result.ok ? "" : `unexpected reject: ${result.reason}`).toBe(true);
      } else {
        expect(result.ok).toBe(false);
        if (!result.ok && expected.reasonContains) {
          expect(result.reason).toContain(expected.reasonContains);
        }
      }
    });
  }
});
